151	    /**
152	     * Handles {@link DuplicateIdentityException} raised when an owner is created whose identity key
153	     * (same normalized telephone, email and last-name sound) matches an existing, non-deleted owner.
154	     *
155	     * @param e The {@link DuplicateIdentityException} to be handled
156	     * @param request {@link HttpServletRequest} object referring to the current request.
157	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
158	     */
159	    @ExceptionHandler(DuplicateIdentityException.class)
160	    @ResponseBody
161	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
162	        HttpStatus status = HttpStatus.CONFLICT;
163	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
164	        return ResponseEntity.status(status).body(detail);
165	    }
