169	     * that already contains the maximum number of owners.
170	     *
171	     * @param e The {@link CityCapacityExceededException} to be handled
172	     * @param request {@link HttpServletRequest} object referring to the current request.
173	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
174	     */
175	    @ExceptionHandler(CityCapacityExceededException.class)
176	    @ResponseBody
177	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
178	        HttpStatus status = HttpStatus.CONFLICT;
179	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
180	        return ResponseEntity.status(status).body(detail);
