184	     * Handles {@link DailyRegistrationLimitExceededException} raised when an owner is created
185	     * after the maximum number of owners for the current day has already been registered.
186	     *
187	     * @param e The {@link DailyRegistrationLimitExceededException} to be handled
188	     * @param request {@link HttpServletRequest} object referring to the current request.
189	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
190	     */
191	    @ExceptionHandler(DailyRegistrationLimitExceededException.class)
192	    @ResponseBody
193	    public ResponseEntity<ProblemDetail> handleDailyRegistrationLimitExceededException(DailyRegistrationLimitExceededException e, HttpServletRequest request) {
194	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
195	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_REACHED);
196	        return ResponseEntity.status(status).body(detail);
